from functools import wraps

CALLS = []


def traced(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        CALLS.append(func.__name__)
        return func(*args, **kwargs)

    return wrapper


@traced
def scan(cell):
    return f"scanned {cell}"


print(scan("north"), scan.__name__, len(CALLS))
